-- Minimal local-only routing source fixtures; never deployed.
CREATE TABLE IF NOT EXISTS public.venues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text);
GRANT ALL ON public.venues TO service_role;
CREATE TABLE public.venue_slug_redirects(old_slug text PRIMARY KEY,venue_id uuid REFERENCES public.venues(id),created_at timestamptz DEFAULT now());
GRANT ALL ON public.venue_slug_redirects TO service_role;
